CREATE INDEX IF NOT EXISTS idx_agent_action_executions_claimable ON agent_action_executions USING btree (status, created_at) WHERE (status = ANY (ARRAY['queued'::text, 'running'::text]));
CREATE INDEX IF NOT EXISTS idx_agent_action_proposals_conversation ON agent_action_proposals USING btree (conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_action_proposals_pending ON agent_action_proposals USING btree (status, expires_at) WHERE (status = ANY (ARRAY['pending'::text, 'approved'::text]));
CREATE INDEX IF NOT EXISTS idx_agent_checkpoints_run_sequence ON agent_checkpoints USING btree (run_id, sequence DESC);
DROP INDEX IF EXISTS idx_agent_summary_jobs_one_queued;
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_summary_jobs_one_queued ON agent_conversation_summary_jobs USING btree (conversation_id) WHERE (status = 'queued'::text);
CREATE INDEX IF NOT EXISTS idx_agent_conversations_user_workspace_updated ON agent_conversations USING btree (user_id, workspace_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_evidence_run_created ON agent_evidence USING btree (run_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_agent_evidence_source ON agent_evidence USING btree (user_id, workspace_id, source_type, source_id);
CREATE INDEX IF NOT EXISTS idx_agent_index_outbox_claimable ON agent_index_outbox USING btree (status, available_at, created_at) WHERE (status = ANY (ARRAY['queued'::text, 'running'::text]));
DROP INDEX IF EXISTS idx_agent_index_outbox_one_queued;
