DO $support$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'trade_review_publications'::regclass AND contype = 'u' AND pg_get_constraintdef(oid, true) = 'UNIQUE (journal_entry_id)') THEN ALTER TABLE trade_review_publications ADD CONSTRAINT trade_review_publications_journal_entry_id_key UNIQUE (journal_entry_id); END IF; END $support$;
DO $support$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'trade_review_versions'::regclass AND contype = 'u' AND pg_get_constraintdef(oid, true) = 'UNIQUE (match_id, version_number)') THEN ALTER TABLE trade_review_versions ADD CONSTRAINT trade_review_versions_match_id_version_number_key UNIQUE (match_id, version_number); END IF; END $support$;
DO $support$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'users'::regclass AND contype = 'u' AND pg_get_constraintdef(oid, true) = 'UNIQUE (clerk_uuid)') THEN ALTER TABLE users ADD CONSTRAINT users_clerk_uuid_key UNIQUE (clerk_uuid); END IF; END $support$;
CREATE OR REPLACE FUNCTION agent_enqueue_index_work(p_user_id text, p_workspace_id text, p_source_type text, p_source_id text, p_operation text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF p_user_id IS NULL OR p_workspace_id IS NULL OR p_source_id IS NULL THEN
        RETURN;
    END IF;
    INSERT INTO agent_index_outbox
        (user_id, workspace_id, source_type, source_id, operation)
    SELECT p_user_id, p_workspace_id, p_source_type, p_source_id, p_operation
    WHERE EXISTS (SELECT 1 FROM users WHERE id = p_user_id)
      AND EXISTS (
          SELECT 1 FROM workspaces WHERE id = p_workspace_id AND user_id = p_user_id
      )
    ON CONFLICT (user_id, workspace_id, source_type, source_id)
        WHERE status = 'queued'
    DO UPDATE SET operation = EXCLUDED.operation, available_at = now(),
                  updated_at = now(), error_code = NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION agent_related_record_index_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    payload JSONB;
    related_id TEXT;
    row_value RECORD;
BEGIN
    payload := to_jsonb(NEW);
    related_id := payload->>'id';
    IF TG_TABLE_NAME = 'tags' THEN
        FOR row_value IN
            SELECT j.user_id, j.workspace_id, j.id
              FROM trade_tags tt JOIN journal_entries j ON j.id = tt.journal_entry_id
             WHERE tt.tag_id = related_id
        LOOP
            PERFORM agent_enqueue_index_work(row_value.user_id, row_value.workspace_id, 'journal_entry', row_value.id, 'upsert');
        END LOOP;
    ELSE
        FOR row_value IN
            SELECT j.user_id, j.workspace_id, j.id
              FROM trade_principle_violations v JOIN journal_entries j ON j.id = v.journal_entry_id
             WHERE v.principle_id = related_id
        LOOP
            PERFORM agent_enqueue_index_work(row_value.user_id, row_value.workspace_id, 'journal_entry', row_value.id, 'upsert');
        END LOOP;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION agent_relationship_index_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    payload JSONB;
    owner_user TEXT;
    owner_workspace TEXT;
    trade_id TEXT;
    note_id TEXT;
BEGIN
    payload := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    IF TG_TABLE_NAME = 'notebook_note_trades' THEN
        note_id := payload->>'note_id';
        trade_id := payload->>'trade_id';
        SELECT user_id, workspace_id INTO owner_user, owner_workspace
          FROM notebook_notes WHERE id = note_id;
        PERFORM agent_enqueue_index_work(owner_user, owner_workspace, 'notebook_note', note_id, 'upsert');
        SELECT user_id, workspace_id INTO owner_user, owner_workspace
          FROM journal_entries WHERE id = trade_id;
        PERFORM agent_enqueue_index_work(owner_user, owner_workspace, 'journal_entry', trade_id, 'upsert');
    ELSE
        trade_id := payload->>'journal_entry_id';
        SELECT user_id, workspace_id INTO owner_user, owner_workspace
          FROM journal_entries WHERE id = trade_id;
        PERFORM agent_enqueue_index_work(owner_user, owner_workspace, 'journal_entry', trade_id, 'upsert');
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
CREATE OR REPLACE FUNCTION agent_source_index_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    payload JSONB;
    source_kind TEXT;
BEGIN
    payload := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    source_kind := CASE TG_TABLE_NAME
        WHEN 'journal_entries' THEN 'journal_entry'
        WHEN 'notebook_notes' THEN 'notebook_note'
        WHEN 'playbooks' THEN 'playbook'
    END;
    PERFORM agent_enqueue_index_work(
        payload->>'user_id', payload->>'workspace_id', source_kind, payload->>'id',
        CASE WHEN TG_OP = 'DELETE' OR payload->>'deleted_at' IS NOT NULL THEN 'delete' ELSE 'upsert' END
    );
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
CREATE OR REPLACE FUNCTION rehome_strategy_library_before_workspace_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE replacement TEXT;
BEGIN
    SELECT id INTO replacement FROM workspaces
    WHERE user_id = OLD.user_id AND id <> OLD.id
    ORDER BY created_at, id LIMIT 1;
    IF replacement IS NOT NULL THEN
        UPDATE playbooks SET workspace_id = replacement WHERE workspace_id = OLD.id;
        UPDATE tag_categories SET workspace_id = replacement WHERE workspace_id = OLD.id;
        UPDATE tags SET workspace_id = replacement WHERE workspace_id = OLD.id;
    END IF;
    RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION reject_trade_review_version_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'trade review versions are immutable; create a correction version';
END;
$function$;
CREATE OR REPLACE FUNCTION set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;
